// arma 2 consultas de investigacion profunda por cuenta
const l=$json;
const emp=l.Empresa||'';
const q1 = `${emp} ${l.Ciudad||''} sitio oficial contacto directivos LinkedIn`;
const q2 = `${emp} ${l.Sector||''} noticias 2025 2026 certificaciones cumplimiento regulatorio sanciones tecnologia`;
return [{json:{...l, q1, q2}}];

// junta resultados y arma el prompt de dossier (estilo /analizar-empresas)
const l=$('Prep investigacion').item.json;
function org(node){ try{const r=$(node).first().json; return (r&&r.organic?r.organic:[]).slice(0,8).map(o=>({t:o.title,l:o.link,s:o.snippet}));}catch(e){return [];} }
const R1=org('Buscar: empresa+contacto'); const R2=org('Buscar: sector+riesgo');
const system=[
'<identidad>Investigador comercial B2B senior y consultor de ciberseguridad/GRC de ACCES GROUP. Construyes un DOSSIER estrategico de cuenta, ejecutivo y accionable, SOLO con lo provisto + conocimiento del portafolio ACCES. Separas dato confirmado / inferencia / pendiente. Citas fuentes (URLs de los resultados). NO inventas cargos, cifras, certificaciones ni noticias; si no aparece, "no encontrado publicamente".</identidad>',
'<portafolio>Consulting (gobierno TI, riesgo, ISO 27001/22301, BIA/BCP/DRP, ciberestrategia), Audit (auditoria de sistemas, cyber auditorias, NIST, regulatoria), Solutions (nube hibrida, redes criticas, ciberseguridad, continuidad, SASE), IT (SOC/NOC/CISO/BaaS as a Service 24x7, pentesting infra/web/APIs/OT, Red/Blue Team, DevSecOps, vishing/phishing), Training.</portafolio>',
'<estructura>Genera un dossier con: 1) Identidad; 2) Sector y criticidades; 3) Riesgos (regulatorio, continuidad, terceros, ciber); 4) Infraestructura tecnologica probable; 5) Cumplimiento aplicable; 6) Business case ACCES (dolor -> impacto -> solucion ACCES entre parentesis, en horizontes 30-90d / 3-12m); 7) Decisores y perfilamiento (rol, que le preocupa, como abrir); 8) Abogado del diablo (por que puede fallar + mitigacion); 9) Siguiente paso CRM. Lenguaje de NEGOCIO, sin jerga.</estructura>',
'<salida>SOLO JSON: {"resumen_ejecutivo":"","dossier_md":"","riesgos_clave":"","business_case_acces":"","decisores":"","abogado_diablo":"","siguiente_paso":"","fuentes":[],"confianza":0,"correos_nuevos":[]}. dossier_md = el dossier completo en Markdown listo para pegar.</salida>'
].join('\n');
const user=`CUENTA: ${l.Empresa} | Micro-ICP ${l.Micro_ICP} | Sector ${l.Sector} | Ciudad ${l.Ciudad||''} ${l.Estado_Region||''}\n`
 +`Contacto conocido: ${l.Contacto||'-'} (${l.Cargo||'-'}) ${l.Correo||''}\nGancho: ${l.Gancho}\nNotas previas: ${l.Notas||''}\n`
 +`--- RESULTADOS WEB (empresa/contacto) ---\n${JSON.stringify(R1,null,1)}\n`
 +`--- RESULTADOS WEB (sector/riesgo/cumplimiento) ---\n${JSON.stringify(R2,null,1)}\n`
 +`Construye el dossier. Devuelve solo el JSON.`;
return [{json:{...l, system, user}}];

let d={};try{const _b=$json.content||[];const _t=_b.find(x=>x&&x.type==='text');d=JSON.parse((_t?_t.text:'{}').replace(/^```json/i,'').replace(/```$/,'').trim());}catch(e){d={dossier_md:'(error de parseo)'};}
const l=$('Armar dossier').item.json;
const hoy=$now.toFormat('yyyy-LL-dd');
// NUNCA borra: si hay correos nuevos y ya habia correo, se suman a Notas
let notas=l.Notas||'';
if(Array.isArray(d.correos_nuevos)&&d.correos_nuevos.length){ notas += ' | correos hallados: '+d.correos_nuevos.join(', '); }
notas += ` | investigado ${hoy} (conf ${d.confianza||0}%)`;
return [{json:{
  // fila para la pestaña Investigacion (append, historial)
  inv:{ Fecha:hoy, ID_Lead:l.ID_Lead, Empresa:l.Empresa, Sector:l.Sector,
        Resumen:(d.resumen_ejecutivo||'').slice(0,500), Dossier_MD:d.dossier_md||'',
        Riesgos_Clave:d.riesgos_clave||'', BusinessCase_ACCES:d.business_case_acces||'',
        Decisores:d.decisores||'', Abogado_Diablo:d.abogado_diablo||'', Siguiente_Paso:d.siguiente_paso||'',
        Fuentes:(d.fuentes||[]).join(' | '), Confianza:d.confianza||0 },
  // update minimo a Leads (no borra nada)
  ID_Lead:l.ID_Lead, Ultima_Investigacion:hoy, Investigar_Profundo:'no', Notas:notas
}}];
